// Cross the assets returned by the search above with the variants named
// in the original webhook body, one output item per (asset, variant) pair.
// Mirrors CampaignBrief.variants from the imagekit-render-creative-automation
// spec so the two templates speak the same shape.
const body = $('Webhook').first().json.body || {};
const variants = Array.isArray(body.variants) ? body.variants : [];
const maxAssets = Number(body.maxAssets) > 0 ? Number(body.maxAssets) : 200;

if (variants.length === 0) {
  throw new Error('Request body must include a non-empty "variants" array, e.g. [{ "name": "square", "query": "resize to 1080x1080" }].');
}

const assets = items.slice(0, maxAssets);
const jobs = [];
for (const asset of assets) {
  for (const variant of variants) {
    jobs.push({
      json: {
        fileId: asset.json.fileId,
        filePath: asset.json.filePath,
        sourceUrl: asset.json.url,
        variantName: variant.name,
        variantQuery: variant.query,
      },
    });
  }
}

return jobs;

// Implements the same async-transformation protocol as
// imagekit-render-creative-automation/src/lib/await-transformation.ts:
// treat `is-intermediate-response: true`, HTTP 202, and HTTP 302 as "not
// ready yet" even though they carry a successful-looking status, retry with
// exponential backoff + jitter (1s, capped at 30s), and surface `ik-error`
// as a hard failure. See that file's header comment for the ImageKit docs
// this is sourced from.
const job = $input.item.json;

function extractUrl(mcpResult) {
  const structured = mcpResult.structuredContent;
  if (structured && typeof structured.url === 'string') return structured.url;
  const content = Array.isArray(mcpResult.content) ? mcpResult.content : [];
  for (const part of content) {
    const text = part && part.text;
    if (typeof text === 'object' && text !== null && typeof text.url === 'string') return text.url;
    if (typeof text === 'string') {
      const match = text.match(/https?:\/\/\S+/);
      if (match) return match[0];
    }
  }
  return undefined;
}

const url = extractUrl(job);
if (!url) {
  return { json: { ...job, status: 'error', error: 'transformation_builder did not return a URL.' } };
}

const timeoutMs = 120000;
const maxDelayMs = 30000;
let delayMs = 1000;
const startedAt = Date.now();

while (true) {
  const response = await helpers.httpRequest({
    method: 'GET',
    url,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    disableFollowRedirect: true,
    timeout: 30000,
  });

  const headers = response.headers || {};
  const isIntermediate = String(headers['is-intermediate-response'] || '').toLowerCase() === 'true';
  const ikError = headers['ik-error'];
  const status = response.statusCode;

  if (ikError) {
    return { json: { ...job, url, status: 'error', error: String(ikError) } };
  }

  const notReady = isIntermediate || status === 202 || status === 302;
  if (!notReady && status >= 200 && status < 300) {
    return { json: { ...job, url, status: 'ready' } };
  }

  const elapsed = Date.now() - startedAt;
  if (elapsed >= timeoutMs) {
    return { json: { ...job, url, status: 'timeout' } };
  }

  const jitteredDelay = delayMs * (0.5 + Math.random() * 0.5);
  const sleepMs = Math.min(jitteredDelay, timeoutMs - elapsed);
  await new Promise((resolve) => setTimeout(resolve, sleepMs));
  delayMs = Math.min(delayMs * 2, maxDelayMs);
}
